package vn.iotstar.service; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.iotstar.entity.*; import vn.iotstar.repository.OtpTokenRepository; import java.security.SecureRandom; import java.time.*;
@Service @RequiredArgsConstructor public class OtpService{final OtpTokenRepository repo;final MailService mail;final SecureRandom random=new SecureRandom();@Value("${app.otp.expiry-minutes:10}")long expiry;@Transactional public void issue(String email,OtpPurpose p){repo.deleteByEmailAndPurpose(email,p);String c=String.format("%06d",random.nextInt(1000000));repo.save(new OtpToken(email,c,p,LocalDateTime.now().plusMinutes(expiry)));mail.send(email,c);}@Transactional public void verify(String email,String code,OtpPurpose p){var t=repo.findTopByEmailAndPurposeAndUsedFalseOrderByIdDesc(email,p).orElseThrow(()->new IllegalArgumentException("OTP không tồn tại"));if(!t.valid(code))throw new IllegalArgumentException("OTP sai hoặc hết hạn");t.setUsed(true);repo.save(t);}}
